[💻 Xem project trên GitHub](https://github.com/Huynhcongtu/hct-learning-hub/tree/main/code/extensions/X02_DS1307){ .md-button .md-button--primary } [⬇️ Mở main.c](https://raw.githubusercontent.com/Huynhcongtu/hct-learning-hub/main/code/extensions/X02_DS1307/main.c){ .md-button }   <pre><code>#include "common.h"
#include "uart.h"

PIN(SDA,P1,0);
PIN(SCL,P1,1);

#define DS1307_ADDR 0x68u
#define SET_TIME 0

static void i2c_delay(void) {
    NOP(); NOP(); NOP(); NOP();
}

static u8 scl_high(void) {
    u16 guard=5000u;
    SCL=1;
    while(!SCL &amp;&amp; --guard) { }
    return SCL ? 1u : 0u;
}

static void i2c_start(void) {
    SDA=1; SCL=1; i2c_delay();
    SDA=0; i2c_delay();
    SCL=0;
}

static void i2c_stop(void) {
    SDA=0; i2c_delay();
    scl_high(); i2c_delay();
    SDA=1; i2c_delay();
}

static u8 i2c_write(u8 x) {
    u8 i,ack;

    for(i=0;i&lt;8u;i++) {
        SDA=(x &amp; 0x80u) ? 1 : 0;
        i2c_delay();
        if(!scl_high()) return 0;
        i2c_delay();
        SCL=0;
        x&lt;&lt;=1;
    }

    SDA=1;
    i2c_delay();
    if(!scl_high()) return 0;
    ack=(SDA==0);
    SCL=0;
    return ack;
}

static u8 i2c_read(u8 ack) {
    u8 i,x=0;

    SDA=1;
    for(i=0;i&lt;8u;i++) {
        x&lt;&lt;=1;
        if(!scl_high()) return 0;
        if(SDA) x|=1u;
        SCL=0;
    }

    SDA=ack ? 0 : 1;
    i2c_delay();
    scl_high();
    SCL=0;
    SDA=1;

    return x;
}

static u8 ds1307_write_reg(u8 reg,u8 value) {
    i2c_start();
    if(!i2c_write((u8)(DS1307_ADDR&lt;&lt;1))) { i2c_stop(); return 0; }
    if(!i2c_write(reg))                  { i2c_stop(); return 0; }
    if(!i2c_write(value))                { i2c_stop(); return 0; }
    i2c_stop();
    return 1;
}

static u8 ds1307_read_hms(u8 *hh,u8 *mm,u8 *ss) {
    i2c_start();
    if(!i2c_write((u8)(DS1307_ADDR&lt;&lt;1))) { i2c_stop(); return 0; }
    if(!i2c_write(0x00u))                { i2c_stop(); return 0; }

    i2c_start();
    if(!i2c_write((u8)((DS1307_ADDR&lt;&lt;1)|1u))) { i2c_stop(); return 0; }

    *ss=i2c_read(1);
    *mm=i2c_read(1);
    *hh=i2c_read(0);
    i2c_stop();

    if((*ss &amp; 0x80u)!=0u) return 0; /* CH must be 0 */
    if((*hh &amp; 0x40u)!=0u) return 0; /* sample expects 24-hour mode */

    return 1;
}

void main(void) {
    u8 hh,mm,ss;

    EA=0;
    SDA=1; SCL=1;
    uart_init();
    uart_puts("DS1307 READY\r\n");

#if SET_TIME
    ds1307_write_reg(0x00u,0x00u);
    ds1307_write_reg(0x01u,0x00u);
    ds1307_write_reg(0x02u,0x12u);
#endif

    for(;;) {
        if(ds1307_read_hms(&amp;hh,&amp;mm,&amp;ss)) {
            uart_hex(hh); uart_putc(':');
            uart_hex(mm); uart_putc(':');
            uart_hex(ss); uart_puts("\r\n");
        } else {
            uart_puts("RTC ERROR\r\n");
        }

        /* Deliberately simple teaching loop; not a calibrated 1 s scheduler. */
        {
            u16 wait=60000u;
            while(--wait) { NOP(); }
        }
    }
}
</code></pre> <p>Info</p> <p>Đây là SUPPLEMENTAL implementation được viết theo yêu cầu của bài mở rộng/project trong học liệu. Tài liệu nguồn không cung cấp nguyên văn chương trình đầy đủ này.</p>

[💻 Xem project trên GitHub](https://github.com/Huynhcongtu/hct-learning-hub/tree/main/code/extensions/X01_Keypad){ .md-button .md-button--primary } [⬇️ Mở main.c](https://raw.githubusercontent.com/Huynhcongtu/hct-learning-hub/main/code/extensions/X01_Keypad/main.c){ .md-button }   <pre><code>#include "common.h"
#include "delay.h"
#include "uart.h"

u8 ROM keymap[16]={
    '1','2','3','A',
    '4','5','6','B',
    '7','8','9','C',
    '*','0','#','D'
};

/* Returns 0xFF when no valid single key is detected.
 * Rows=P1.0..P1.3, columns=P1.4..P1.7, columns pulled up. */
static u8 keypad_scan_once(void) {
    u8 row,cols,col;

    for(row=0;row&lt;4u;row++) {
        P1=0xFFu;
        P1 &amp;= (u8)~(1u&lt;&lt;row);
        NOP(); NOP();

        cols=(u8)((P1&gt;&gt;4)&amp;0x0Fu);
        if(cols!=0x0Fu) {
            for(col=0;col&lt;4u;col++) {
                if((cols &amp; (1u&lt;&lt;col))==0u)
                    return keymap[row*4u+col];
            }
        }
    }

    return 0xFFu;
}

void main(void) {
    u8 stable=0xFFu,candidate=0xFFu,sample,count=0;

    EA=0;
    P1=0xFFu;
    uart_init();
    uart_puts("KEYPAD READY\r\n");

    for(;;) {
        sample=keypad_scan_once();

        if(sample!=candidate) {
            candidate=sample;
            count=0;
        } else if(count&lt;4u) {
            ++count;
            if(count==4u &amp;&amp; stable!=candidate) {
                stable=candidate;
                if(stable!=0xFFu) {
                    uart_puts("KEY=");
                    uart_putc(stable);
                    uart_puts("\r\n");
                }
            }
        }

        delay_ms(5);
    }
}
